const DEFAULT_REVIEWS_DATA=[{id:"r1",author:"Krys Boyer",role:"Google Local Guide · 10 reviews · 13 photos",rating:"★★★★★",quote:"Stopped in on a spontaneous road trip through Scott City needing an oil change and laundromat nearby — and found The Grill House right around the corner. Spotless dining room, incredible home-style cooking, and hospitality that made us feel right at home!",dish:"Hand-Cut Steaks & Breakfast"},{id:"r2",author:"One Delightful Life",role:"Verified Food & Travel Reviewer",rating:"★★★★★",quote:"A must-visit spot in Scott City, Kansas! The Country Fried Steak and hand-cut ribeye are cooked to perfection. Generous portions, fair prices, and friendly counter service.",dish:"Country Fried Steak"},{id:"r3",author:"Marcus T.",role:"Google Local Guide · 24 reviews",rating:"★★★★★",quote:"Best breakfast in Scott City by far, and served all day! The chorizo potato burrito and all-meat omelette with hash browns are unmatched. Super clean atmosphere and attentive staff.",dish:"Chorizo Burrito & Hash Browns"},{id:"r4",author:"Sarah & Dan R.",role:"Verified Road Trip Diners",rating:"★★★★★",quote:"Great family diner on 5th Street. Generous plates of both Mexican specialties and classic American diner food. The carne asada tacos and hash browns are fantastic.",dish:"Carne Asada Tacos"},{id:"r5",author:"David K.",role:"Tripadvisor Verified Diner",rating:"★★★★★",quote:"Immaculate hospitality! The staff greets you like family. If you're driving through Kansas on East 5th Street, this is a top-notch local dining stop.",dish:"American & Mexican Grill"}];function getReviewsData(){try{const e=localStorage.getItem("the_grill_house_reviews");if(e){const t=JSON.parse(e);if(Array.isArray(t)&&t.length>0)return t}}catch(e){console.warn("Could not parse reviews data from localStorage, falling back to defaults:",e)}return DEFAULT_REVIEWS_DATA}function saveReviewsData(e){try{return localStorage.setItem("the_grill_house_reviews",JSON.stringify(e)),window.REVIEWS_DATA=e,!0}catch(e){return console.error("Failed to save reviews data:",e),!1}}function resetReviewsData(){try{return localStorage.removeItem("the_grill_house_reviews"),localStorage.removeItem("the_grill_house_pending_reviews"),window.REVIEWS_DATA=DEFAULT_REVIEWS_DATA,!0}catch(e){return console.error("Failed to reset reviews data:",e),!1}}function getPendingReviews(){try{const e=localStorage.getItem("the_grill_house_pending_reviews");if(e){const t=JSON.parse(e);if(Array.isArray(t))return t}}catch(e){console.warn("Could not parse pending reviews:",e)}return[]}function savePendingReviews(e){try{return localStorage.setItem("the_grill_house_pending_reviews",JSON.stringify(e)),!0}catch(e){return console.error("Failed to save pending reviews:",e),!1}}function addPendingReview(e){const t=getPendingReviews();t.unshift(e),savePendingReviews(t)}function approvePendingReview(e){const t=getPendingReviews(),r=t.findIndex(t=>t.id===e);if(-1===r)return!1;const[i]=t.splice(r,1);savePendingReviews(t);const a=getReviewsData();return a.unshift(i),saveReviewsData(a),!0}function rejectPendingReview(e){return savePendingReviews(getPendingReviews().filter(t=>t.id!==e)),!0}var REVIEWS_DATA=getReviewsData();